import React, { useEffect } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { Muestra_Cards } from '../../../Redux/Actions/Usuario/Action-user';
import './ZatosCards.css';
import ZapatosCard from './card/Zapatos_Card';

const ZapatosCards = () => {
  const dispatch = useDispatch();
  const cards = useSelector((state) => state.CARDS || []);
  const User = useSelector((state) => state.USER || []);
  const empresa = useSelector((state) => state.EMPRESA || []);

  useEffect(() => {
    dispatch(Muestra_Cards());
  }, [dispatch]);

  return (
    <div className="zapatos-cards">
      {cards
        .filter(card => card.activo === true)
        .map((card) => (
          <ZapatosCard
            key={card.id}
            id={card.id}
            marca={card.marca}
            costo={card.costo}
            color={card.color}
            modelo={card.modelo}
            calidad={card.calidad}
            descripcion={card.descripcion}
            url={card.url}
            talla={card.talla}
            activo={card.activo}
          />
        ))}
    </div>
  );
}

export default ZapatosCards;
